CREATE OR REPLACE FUNCTION public.user_effective_permissions(_user_id uuid) RETURNS TABLE(permission_key text,source text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ WITH role_perms AS (SELECT rp.permission_key AS k FROM public.user_roles ur JOIN public.role_permissions rp ON (rp.role_key=ur.role::text OR (ur.role='owner' AND rp.role_key='admin')) WHERE ur.user_id=_user_id), active_overrides AS (SELECT permission_key AS k,granted FROM public.user_permission_overrides WHERE user_id=_user_id AND (expires_at IS NULL OR expires_at>now())) SELECT DISTINCT k AS permission_key,CASE WHEN k IN(SELECT k FROM active_overrides WHERE granted=true) THEN 'grant' ELSE 'role' END AS source FROM(SELECT k FROM role_perms UNION SELECT k FROM active_overrides WHERE granted=true) g WHERE k NOT IN(SELECT k FROM active_overrides WHERE granted=false) $$;